import{_ as e}from"./chunks/100.Bym1HttY.js";import{_ as o,o as a,c as r,ak as i}from"./chunks/framework.Ba6sv-31.js";const n="/projects/AiBlockSensor/en/latest/assets/1.BxnBwzPK.webp",s="/projects/AiBlockSensor/en/latest/assets/2.pTOz4ZCl.webp",l="/projects/AiBlockSensor/en/latest/assets/3.D-XFu27x.webp",c="/projects/AiBlockSensor/en/latest/assets/4.Cht2swqf.webp",h="/projects/AiBlockSensor/en/latest/assets/5.jtaFoxbZ.webp",y=JSON.parse('{"title":"6. Light Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/6. Light Sensor.md","filePath":"docs/6. Light Sensor.md"}'),d={name:"docs/6. Light Sensor.md"};function g(p,t,m,u,_,b){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="_6-light-sensor" tabindex="-1">6. Light Sensor <a class="header-anchor" href="#_6-light-sensor" aria-label="Permalink to &quot;6. Light Sensor&quot;">​</a></h1><h2 id="_6-1-introduction" tabindex="-1">6.1 Introduction <a class="header-anchor" href="#_6-1-introduction" aria-label="Permalink to &quot;6.1 Introduction&quot;">​</a></h2><p>This section introduces the light sensor, which detects ambient light intensity. It is commonly used to create interactive projects that respond to changing light levels, such as automatic streetlights and environmental monitoring systems.</p><img loading="lazy" height="348" width="591" src="'+n+'" class="common_img" style="width:300px;"><h2 id="_6-2-technical-specifications" tabindex="-1">6.2 Technical Specifications <a class="header-anchor" href="#_6-2-technical-specifications" aria-label="Permalink to &quot;6.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 17.2 mm</td></tr></tbody></table><h2 id="_6-3-hands-on-project" tabindex="-1">6.3 Hands-On Project <a class="header-anchor" href="#_6-3-hands-on-project" aria-label="Permalink to &quot;6.3 Hands-On Project&quot;">​</a></h2><h3 id="_6-3-1-project-introduction" tabindex="-1">6.3.1 Project Introduction <a class="header-anchor" href="#_6-3-1-project-introduction" aria-label="Permalink to &quot;6.3.1 Project Introduction&quot;">​</a></h3><p>This project uses the light sensor to read ambient light analog values and print them to the serial port. Covering or shining light on the sensor changes the light intensity. Checking the data changes in the serial monitor helps clarify how the light sensor detects ambient light.</p><h3 id="_6-3-2-hardware-wiring" tabindex="-1">6.3.2 Hardware Wiring <a class="header-anchor" href="#_6-3-2-hardware-wiring" aria-label="Permalink to &quot;6.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the light sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="416" width="1039" src="'+s+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among A, B, C, or D on the controller. Ensure that the port selected in the program matches the physical wiring.</strong></p></div><h3 id="_6-3-3-adding-extensions" tabindex="-1">6.3.3 Adding Extensions <a class="header-anchor" href="#_6-3-3-adding-extensions" aria-label="Permalink to &quot;6.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Light sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_6-3-4-complete-program-and-analysis" tabindex="-1">6.3.4 Complete Program and Analysis <a class="header-anchor" href="#_6-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;6.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, continuously read the light analog value from the light sensor on port A.</p></li><li><p>Print the light analog value to the serial port.</p></li><li><p>Wait 0.5 seconds to slow down data refresh for steady observation.</p></li></ol><img loading="lazy" height="263" width="822" src="'+c+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1fLfLXEVjSMZdojOq7C44xJqZIBm4MDem?usp=sharing" target="_blank" rel="noreferrer">Program Files/ 06 Light Sensor.sb3</a>.</strong></p></div><h3 id="_6-3-5-program-upload" tabindex="-1">6.3.5 Program Upload <a class="header-anchor" href="#_6-3-5-program-upload" aria-label="Permalink to &quot;6.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h3 id="_6-3-6-program-outcome" tabindex="-1">6.3.6 Program Outcome <a class="header-anchor" href="#_6-3-6-program-outcome" aria-label="Permalink to &quot;6.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, check the serial monitor in the lower-right corner of the programming software. In bright lighting conditions, the serial monitor shows higher readings. Covering the light sensor reduces light exposure, causing the readings to drop. The readings range from 0 to 100.</p><img loading="lazy" height="953" width="1484" src="'+h+'" class="common_img" style="width:800px;">',26)])])}const w=o(d,[["render",g]]);export{y as __pageData,w as default};
